select.where:
status = 1
and deleted_at is null

    and exists (
        select 1
        from holidays_tour_itinerary hti
        where hti.tour_id = holidays_tour.id
          and (
              hti.from_destination_id in

                  #{destinationId}

              or hti.to_destination_id in

                  #{destinationId}

          )
    )


    and travel_style in

        #{code}



    and exists (
        select 1
        from holidays_tour_tag_rel httr
        where httr.tour_id = holidays_tour.id
          and httr.dict_code in

              #{code}

    )


    and duration_days >= #{query.minDurationDays}


    and duration_days <= #{query.maxDurationDays}


    and (
        holidays_tour.code like concat('%', #{query.keyword}, '%')
        or holidays_tour.name like concat('%', #{query.keyword}, '%')
        or exists (
            select 1
            from holidays_tour_search hts
            where hts.tour_id = holidays_tour.id
              and hts.status = 1
              and (
                  hts.code like concat('%', #{query.keyword}, '%')
                  or hts.name like concat('%', #{query.keyword}, '%')
                  or hts.search_text like concat('%', #{query.keyword}, '%')
              )
        )
    )

mapper.select:
status = 1 and deleted_at is null and (sale_price is not null or base_price is not null)
and exists ( select 1 from holidays_tour_itinerary hti where hti.tour_id = holidays_tour.id and ( hti.from_destination_id in
#{destinationId}
or hti.to_destination_id in
#{destinationId}
) )
and 1 = 0
order by coalesce(sale_price, base_price) asc, id desc limit 1
